const e=[{id:"gaming-001",text:"What is better? To be born good or to overcome your evil nature through great effort?",author:"Paarthurnax",source:"The Elder Scrolls V: Skyrim",category:"gaming",license:"Fair Use",difficulty:"medium",length:85},{id:"gaming-002",text:"The cosmos, and all the stars, are ours to explore.",author:"Commander Shepard",source:"Mass Effect",category:"gaming",license:"Fair Use",difficulty:"easy",length:51},{id:"gaming-003",text:"You are filled with determination.",author:"Narrator",source:"Undertale",category:"gaming",license:"Fair Use",difficulty:"easy",length:34},{id:"gaming-004",text:"We are defined by the choices we make, not the circumstances of our birth.",author:"Geralt of Rivia",source:"The Witcher 3: Wild Hunt",category:"gaming",license:"Fair Use",difficulty:"easy",length:74},{id:"gaming-005",text:"Endure and survive.",author:"Ellie",source:"The Last of Us",category:"gaming",license:"Fair Use",difficulty:"easy",length:19},{id:"gaming-006",text:"It is time to finish the fight.",author:"Master Chief",source:"Halo 3",category:"gaming",license:"Fair Use",difficulty:"easy",length:31},{id:"gaming-007",text:"I used to be an adventurer like you, then I took an arrow in the knee.",author:"Guard",source:"The Elder Scrolls V: Skyrim",category:"gaming",license:"Fair Use",difficulty:"easy",length:70},{id:"gaming-008",text:"A hero need not speak. When he is gone, the world will speak for him.",author:"Narrator",source:"Halo",category:"gaming",license:"Fair Use",difficulty:"easy",length:69},{id:"gaming-009",text:"Even the smallest decision can change the course of the future.",author:"Narrator",source:"Until Dawn",category:"gaming",license:"Fair Use",difficulty:"easy",length:63},{id:"gaming-010",text:"Stand in the ashes of a trillion dead souls, and ask the ghosts if honor matters. The silence is your answer.",author:"Javik",source:"Mass Effect 3",category:"gaming",license:"Fair Use",difficulty:"medium",length:109},{id:"gaming-011",text:"War. War never changes.",author:"Narrator",source:"Fallout",category:"gaming",license:"Fair Use",difficulty:"easy",length:23},{id:"gaming-012",text:"It's dangerous to go alone! Take this.",author:"Old Man",source:"The Legend of Zelda",category:"gaming",license:"Fair Use",difficulty:"easy",length:38},{id:"gaming-013",text:"The cake is a lie.",author:"Doug Rattmann",source:"Portal",category:"gaming",license:"Fair Use",difficulty:"easy",length:18},{id:"gaming-014",text:"Would you kindly?",author:"Andrew Ryan",source:"BioShock",category:"gaming",license:"Fair Use",difficulty:"easy",length:17},{id:"gaming-015",text:"What is a man? A miserable little pile of secrets.",author:"Dracula",source:"Castlevania: Symphony of the Night",category:"gaming",license:"Fair Use",difficulty:"easy",length:50},{id:"gaming-016",text:"Praise the Sun!",author:"Solaire of Astora",source:"Dark Souls",category:"gaming",license:"Fair Use",difficulty:"easy",length:15},{id:"gaming-017",text:"Do you know the definition of insanity?",author:"Vaas Montenegro",source:"Far Cry 3",category:"gaming",license:"Fair Use",difficulty:"easy",length:39},{id:"gaming-018",text:"Stay awhile and listen!",author:"Deckard Cain",source:"Diablo II",category:"gaming",license:"Fair Use",difficulty:"easy",length:23},{id:"gaming-019",text:"Nothing is true, everything is permitted.",author:"Ezio Auditore",source:"Assassin's Creed",category:"gaming",license:"Fair Use",difficulty:"easy",length:41},{id:"gaming-020",text:"Thank you Mario! But our princess is in another castle!",author:"Toad",source:"Super Mario Bros.",category:"gaming",license:"Fair Use",difficulty:"easy",length:55},{id:"gaming-021",text:"Rise and shine, Mister Freeman. Rise and shine.",author:"G-Man",source:"Half-Life 2",category:"gaming",license:"Fair Use",difficulty:"easy",length:47},{id:"gaming-022",text:"A man chooses, a slave obeys.",author:"Andrew Ryan",source:"BioShock",category:"gaming",license:"Fair Use",difficulty:"easy",length:29},{id:"gaming-023",text:"Even in dark times, we cannot show the darkness our fear.",author:"Mickey Mouse",source:"Kingdom Hearts",category:"gaming",license:"Fair Use",difficulty:"easy",length:57},{id:"gaming-024",text:"The right man in the wrong place can make all the difference in the world.",author:"G-Man",source:"Half-Life 2",category:"gaming",license:"Fair Use",difficulty:"easy",length:74},{id:"gaming-025",text:"Good men mean well. We just don't always end up doing well.",author:"Isaac Clarke",source:"Dead Space 3",category:"gaming",license:"Fair Use",difficulty:"easy",length:59},{id:"gaming-026",text:"Some tree branches seem very strong, but if you put too much weight on them, they will break. That is why you must test them first.",author:"General Guide",source:"Minecraft",category:"gaming",license:"Fair Use",difficulty:"medium",length:131},{id:"gaming-027",text:"No cost too great. No mind to think. No will to break. No voice to cry suffering.",author:"The Pale King",source:"Hollow Knight",category:"gaming",license:"Fair Use",difficulty:"medium",length:81},{id:"gaming-028",text:"We all make choices, but in the end our choices make us.",author:"Andrew Ryan",source:"BioShock",category:"gaming",license:"Fair Use",difficulty:"easy",length:56},{id:"gaming-029",text:"History is written by the victors.",author:"General Shepherd",source:"Call of Duty: Modern Warfare 2",category:"gaming",license:"Fair Use",difficulty:"easy",length:34},{id:"gaming-030",text:"It is a beautiful day outside. Birds are singing, flowers are blooming. On days like these, kids like you should be burning in hell.",author:"Sans",source:"Undertale",category:"gaming",license:"Fair Use",difficulty:"medium",length:132},{id:"gaming-031",text:"Despite everything, it's still you.",author:"Narrator",source:"Undertale",category:"gaming",license:"Fair Use",difficulty:"easy",length:35},{id:"gaming-032",text:"Don't wish it were easier. Wish you were better.",author:"Chief",source:"Animal Crossing",category:"gaming",license:"Fair Use",difficulty:"easy",length:48},{id:"gaming-033",text:"A famous explorer once said, that the extraordinary is in what we do, not who we are.",author:"Lara Croft",source:"Tomb Raider",category:"gaming",license:"Fair Use",difficulty:"medium",length:85},{id:"gaming-034",text:"You can't defeat me. I've got the power of determination.",author:"Frisk",source:"Undertale",category:"gaming",license:"Fair Use",difficulty:"easy",length:57},{id:"gaming-035",text:"Protocol 3: I will not lose another pilot.",author:"BT-7274",source:"Titanfall 2",category:"gaming",license:"Fair Use",difficulty:"easy",length:42},{id:"gaming-036",text:"You can't use the fire exit because you're not made of fire.",author:"",source:"Undertale",category:"gaming",license:"Fair Use",difficulty:"easy",length:60},{id:"gaming-037",text:"Are you trying to impress me? What would impress me more is if you never did that again.",author:"",source:"Portal 2",category:"gaming",license:"Fair Use",difficulty:"medium",length:88},{id:"gaming-038",text:"Where do you think you're going? Because I don't think you're going where you think you're going.",author:"",source:"Portal",category:"gaming",license:"Fair Use",difficulty:"medium",length:97},{id:"gaming-039",text:"And so we meet at last. You are to be commended for avoiding my traps. The work of a man who once had too much time on his hands, and now finds time for nothing but the work of salvation.",author:"",source:"Half-Life",category:"gaming",license:"Fair Use",difficulty:"hard",length:187},{id:"gaming-040",text:"Stupid, pitiful creature. I am the rage in your heart. I am the fury in your thoughts. I alone empowered you to bring chaos to this world, and by the endless void, you shall!",author:"",source:"Warcraft III",category:"gaming",license:"Fair Use",difficulty:"hard",length:174},{id:"gaming-041",text:"Apparently, it only appears to those people who are pure of heart and have a strong desire to see it.",author:"",source:"Pokemon",category:"gaming",license:"Fair Use",difficulty:"medium",length:101},{id:"gaming-042",text:"While monsters are mostly made of magic, human beings are mostly made of water.",author:"",source:"Undertale",category:"gaming",license:"Fair Use",difficulty:"easy",length:79},{id:"gaming-043",text:"It's not about changing the world. It's about doing our best to leave the world the way it is. It's about respecting the will of others, and believing in your own.",author:"",source:"Metal Gear Solid",category:"gaming",license:"Fair Use",difficulty:"hard",length:163},{id:"gaming-044",text:"For the days of my life have vanished like smoke, and my bones are parched like ash, and let all my impurities be as fuel for that fire until nothing remains but the light alone.",author:"",source:"Half-Life",category:"gaming",license:"Fair Use",difficulty:"hard",length:178},{id:"gaming-045",text:"Whenever there is a meeting, a parting shall follow. But that parting needs not last forever. Whether a parting be forever or merely for a short while... that is up to you.",author:"",source:"The Legend of Zelda",category:"gaming",license:"Fair Use",difficulty:"hard",length:172},{id:"gaming-046",text:"In order to return the power to repel evil to your sword, you must find another to take my stead in this temple and ask the gods for their assistance. You must find the one who carries on my bloodline... The one who holds this sacred instrument.",author:"",source:"The Legend of Zelda",category:"gaming",license:"Fair Use",difficulty:"hard",length:245},{id:"gaming-047",text:"Words have the power to both destroy and heal. When words are both true and kind, they can change our world.",author:"",source:"Civilization",category:"gaming",license:"Fair Use",difficulty:"medium",length:108},{id:"gaming-048",text:"Do you understand the expense people went through to keep you locked up in that tower? You think people like that are just gonna let you walk away? You are an investment and you will not be safe until you are far away from here.",author:"",source:"BioShock",category:"gaming",license:"Fair Use",difficulty:"hard",length:228},{id:"gaming-049",text:"How much longer is this going to go on, do you think? Do you have an estimate? Are you sure you shouldn't just quit right now? Seriously, think about it. I can tell you're just going to get more sentimental from here on out. There's still time, you know. Are you sure we shouldn't just turn around and take you back to your island?",author:"",source:"The Legend of Zelda",category:"gaming",license:"Fair Use",difficulty:"hard",length:331},{id:"gaming-050",text:"Sitting back and doing nothing, or worse, criticizing others, does not require courage. Speaking up and letting your unique voice be heard is an important step for anyone who wants to make anything better.",author:"",source:"The Legend of Zelda",category:"gaming",license:"Fair Use",difficulty:"hard",length:205},{id:"gaming-051",text:"Rise and shine, Mister Freeman. Rise and shine. Not that I wish to imply you have been sleeping on the job. No one is more deserving of a rest, and all the effort in the world would have gone to waste until... well, let's just say your hour has come again.",author:"",source:"Half-Life",category:"gaming",license:"Fair Use",difficulty:"hard",length:256},{id:"gaming-052",text:"Allow me to tell you about some complex feelings. Feelings like the joy of finding another pasta lover. The admiration for another's puzzle-solving skills. The desire to have a cool, smart person think you are cool. These feelings... They must be what you are feeling right now! I can hardly imagine what it must be like to feel that way.",author:"",source:"Undertale",category:"gaming",license:"Fair Use",difficulty:"hard",length:338},{id:"gaming-053",text:"In our world, every storm has an end. Every night brings a new morning. What's important is to trust those you love, and never give up. We must all keep hope alive.",author:"",source:"Chrono Trigger",category:"gaming",license:"Fair Use",difficulty:"hard",length:164},{id:"gaming-054",text:"When I was a young man, I had liberty, but I did not see it. I had time, but I did not know it. And I had love, but I did not feel it. Many decades would pass before I understood the meaning of all three. And now, the twilight of my life, this understanding has passed into contentment.",author:"",source:"Assassin's Creed",category:"gaming",license:"Fair Use",difficulty:"hard",length:286},{id:"gaming-055",text:"I'm happy to put this all behind us and get back to work. After all, we've got a lot to do, and only sixty more years to do it. More or less. I don't have the actuarial tables in front of me.",author:"",source:"Portal 2",category:"gaming",license:"Fair Use",difficulty:"hard",length:191},{id:"gaming-056",text:"I don't know what you're talking about. I don't agree with what you're saying. And you're trying to wind me up. But I'm very, very angry, and I want this conversation to stop right away.",author:"",source:"Grand Theft Auto",category:"gaming",license:"Fair Use",difficulty:"hard",length:186},{id:"gaming-057",text:"Our minds are born festering with sin. Some are so blighted, they will never find redemption. The mind must not be pulled from the roots. My children are without blame, without fault - and without choice. For what is the value of will when the spirit is found wanting?",author:"",source:"BioShock",category:"gaming",license:"Fair Use",difficulty:"hard",length:268},{id:"gaming-058",text:"Ok doc, before you hit the road you might wanna grab some medkits, restock on ammo, maybe check the map to see where you are headed. There is an ammo supply crate on the back of the car if that is any comfort. Stay with the car, make use of the thumpers, and you will stand a fair chance against the antlions. I will radio ahead to let the next base know you are coming.",author:"",source:"Half-Life",category:"gaming",license:"Fair Use",difficulty:"hard",length:370},{id:"gaming-059",text:"This island of merchants is home to many valuable goods. While the sail must come first, do not feel limited to buying only it. Once you have it, feel free to stock up on anything else you think you may need. But remember: there is no time to play. Come back immediately as soon as your errands are done.",author:"",source:"The Legend of Zelda",category:"gaming",license:"Fair Use",difficulty:"hard",length:304},{id:"gaming-060",text:"Nothing drives down real estate prices like a good old-fashioned gang war. Apart from an outbreak of plague, but that may be going too far in this case.",author:"",source:"Grand Theft Auto",category:"gaming",license:"Fair Use",difficulty:"hard",length:152},{id:"gaming-061",text:"Oh, you're leaving... I always knew that one day, this day would come. I've always known we're so different, and I'm not sad, because you have a lot ahead of you. I want you to take this. Don't forget me.",author:"",source:"The Legend of Zelda",category:"gaming",license:"Fair Use",difficulty:"hard",length:204},{id:"gaming-062",text:"If I had known you were going to come straight up to my office I would not have bothered hunting you in the first place.",author:"",source:"Half-Life",category:"gaming",license:"Fair Use",difficulty:"medium",length:120},{id:"gaming-063",text:"People know what they do; frequently they know why they do what they do; but what they don't know is what what they do does.",author:"",source:"Civilization",category:"gaming",license:"Fair Use",difficulty:"medium",length:124},{id:"gaming-064",text:"With gene therapy, we can remove those genes which we know may lead to sickness or disease, and at the same time, splice in genes with beneficial effects such as resistance to cancer for example.",author:"",source:"Metal Gear Solid",category:"gaming",license:"Fair Use",difficulty:"hard",length:195},{id:"gaming-065",text:"Using the laser guide, you can steer your rocket past the gunship defenses and prevent it from shooting down your rocket. This will only anger it at first. But if you can survive long enough to make several direct hits, you will be rewarded with a prize worthy of any mantle piece.",author:"",source:"Half-Life",category:"gaming",license:"Fair Use",difficulty:"hard",length:281},{id:"gaming-066",text:"I think she wanted you, of all people, to know the truth. She wanted to live on in your memory, not as a soldier, but as a woman. But - she was forbidden to tell you herself. And that's why she told me. Snake, history will never know what she did. No one will ever learn the truth. Her story... her debriefing, will endure only in your heart. Everything she did, she did for her country. She sacrificed her life and her honor for her native land. She was a real hero. She was a true patriot.",author:"",source:"Metal Gear Solid",category:"gaming",license:"Fair Use",difficulty:"hard",length:491},{id:"gaming-067",text:"It's strange, but the way you look right now sort of looks like this tree. It looks all dark and gloomy, almost like it could start crying any second now. How sad...",author:"",source:"The Legend of Zelda",category:"gaming",license:"Fair Use",difficulty:"hard",length:165},{id:"gaming-068",text:"For years I've been rushing around, taking whatever I fancied, not giving a tinker's curse for those I hurt. Yet here I am... with riches and reputation, feeling no wiser than when I left home. Yet when I turn around, and look at the course I've run... there's not a man or woman that I love left standing beside me.",author:"",source:"Assassin's Creed",category:"gaming",license:"Fair Use",difficulty:"hard",length:316},{id:"gaming-069",text:"So it was that over the course of time, the man and the weapon seemed as one. Ashbringer became a name of legend, attributed not just to the fearsome blade but also to the relentless knight who wielded it.",author:"",source:"Warcraft III",category:"gaming",license:"Fair Use",difficulty:"hard",length:205},{id:"gaming-070",text:"Don't look so disappointed, dear one. Just try them on. Today is a day to celebrate. It is the day that you become the same age as the young hero spoken of in all the legends. You only have to wear them for one day, so don't look so down. Be proud, child. In the olden days, this was the day the boys were finally considered to be men. They were taught the ways of the sword to prepare them for battle with their enemies. But we don't live in such a way any longer. Our ways are the ways of peace.",author:"",source:"The Legend of Zelda",category:"gaming",license:"Fair Use",difficulty:"hard",length:497},{id:"gaming-071",text:"She said that she had just joined up as a new recruit. She said they threw her in prison because she refused to take part in the rebellion. I gave her the key. Looks like she managed to break out of here though. I hope she's okay.",author:"",source:"Metal Gear Solid",category:"gaming",license:"Fair Use",difficulty:"hard",length:230},{id:"gaming-072",text:"You cannot defeat me with a blade that does not sparkle with the power to repel evil! What you hold is useless. Go back to the world below, and tell that to the pathetic fools who made this blade! Its power is gone, and its edges are dull!",author:"",source:"The Legend of Zelda",category:"gaming",license:"Fair Use",difficulty:"hard",length:239},{id:"gaming-073",text:"Most test subjects do experience some cognitive deterioration after a few months in suspension. Now you've been under for... quite a lot longer, and it's not out of the question that you might have a very minor case of serious brain damage.",author:"",source:"Portal 2",category:"gaming",license:"Fair Use",difficulty:"hard",length:240},{id:"gaming-074",text:"Even if the morrow is barren of promises, nothing shall forestall my return. To become the dew that quenches the land, to spare the sands, the seas, the skies, I offer thee this silent sacrifice.",author:"",source:"Final Fantasy",category:"gaming",license:"Fair Use",difficulty:"hard",length:195},{id:"gaming-075",text:"I once lived in the Lost Woods, until the day I wandered into a magic transporter. The power of the Dark World quickly turned me into this tree shape. I guess the two forests are connected with each other.",author:"",source:"The Legend of Zelda",category:"gaming",license:"Fair Use",difficulty:"hard",length:205},{id:"gaming-076",text:"The mother was gravely injured. Her only choice was to entrust the child to the Deku Tree, the guardian spirit of the forest. The Deku Tree could sense that this was a child of destiny, whose fate would affect the entire world, so he took him into the forest.",author:"",source:"The Legend of Zelda",category:"gaming",license:"Fair Use",difficulty:"hard",length:259},{id:"gaming-077",text:"Music finds a comfortable parallel with that of human language. Much as language has words, sentences, and stories, music has tones, melodies, and songs.",author:"",source:"Civilization",category:"gaming",license:"Fair Use",difficulty:"hard",length:153},{id:"gaming-078",text:"For it was said that they had become like those peculiar demons which dwell in matter, but in which no light may be found.",author:"",source:"Half-Life",category:"gaming",license:"Fair Use",difficulty:"medium",length:122},{id:"gaming-079",text:"There is an old building up ahead. A bank or museum or something like that. Whatever the hell it used to be, now it is a nexus for Overwatch in City 17. It is the main source of pain for this part of town, thanks to a huge suppression device that rains down hell from the roof of the place.",author:"",source:"Half-Life",category:"gaming",license:"Fair Use",difficulty:"hard",length:290},{id:"gaming-080",text:"You have an urgent look about you... Has something happened? Whatever it is, from the look on your face I suspect that it is no laughing matter.",author:"",source:"The Legend of Zelda",category:"gaming",license:"Fair Use",difficulty:"medium",length:144},{id:"gaming-081",text:"Desmond? I heard your name once before Desmond, a long time ago. And now it lingers in my mind like an image from an old dream. I do not know where you are, or by what means you can hear me. But I know you are listening. I have lived my life as best I could, not knowing its purpose, but drawn forward like a moth to a distant moon. And here, at last, I discover a strange truth. That I am only a conduit for a message that eludes my understanding. Who are we, who have been so blessed to share our stories like this? To speak across centuries? Maybe you will answer all the questions I have asked. Maybe you will be the one to make all this suffering worth something in the end.",author:"",source:"Assassin's Creed",category:"gaming",license:"Fair Use",difficulty:"hard",length:679},{id:"gaming-082",text:"The ancient Oracle said that I was the wisest of all the Greeks. It is because I alone, of all the Greeks, know that I know nothing.",author:"",source:"Civilization",category:"gaming",license:"Fair Use",difficulty:"medium",length:132},{id:"gaming-083",text:"Comstock says all this trouble, all this strife, is on our heads. Says we're to blame. Says ain't nobody got nothing to complain about, and if it's not fine for you and yours, that's 'cause you a backslider and you've fallen into sin.",author:"",source:"BioShock",category:"gaming",license:"Fair Use",difficulty:"hard",length:234},{id:"gaming-084",text:"The scientists were always hanging cores on me to regulate my behavior. I've heard voices all my life. But now I hear the voice of a conscience, and it's terrifying, because for the first time it's my voice.",author:"",source:"Portal 2",category:"gaming",license:"Fair Use",difficulty:"hard",length:207},{id:"gaming-085",text:"What a fool you are. I'm a god, how can you kill a god? What a grand and intoxicating innocence. How could you be so naive? There is no escape. No recall or intervention can work in this place. Come, lay down your weapons, it is not too late for my mercy.",author:"",source:"The Elder Scrolls",category:"gaming",license:"Fair Use",difficulty:"hard",length:255},{id:"gaming-086",text:"Colors weave into a spire of flame. Distant sparks call to a past still unnamed. Bear this torch against the cold of the night. Search your soul and re-awaken the undying light! On that day, when the sky fell away, our world came to an end. In our eyes did a fading sunrise in the dark, glimmering shadows.",author:"",source:"Super Smash Bros",category:"gaming",license:"Fair Use",difficulty:"hard",length:306},{id:"gaming-087",text:"Look at these, they're amazing! Which one do you like more? This one, or this? The bird is beautiful, and the cage is somber, but there's really something special about it. I just can't decide.",author:"",source:"BioShock",category:"gaming",license:"Fair Use",difficulty:"hard",length:193},{id:"gaming-088",text:"I'd just like to point out that you were given every opportunity to succeed. There was even going to be a party for you. A big party that all your friends were invited to. I invited your best friend the companion cube. Of course, he couldn't come because you murdered him. All your other friends couldn't come either because you don't have any other friends.",author:"",source:"Portal",category:"gaming",license:"Fair Use",difficulty:"hard",length:358},{id:"gaming-089",text:"Remember before when I was talking about smelly garbage standing around being useless? That was a metaphor. I was actually talking about you. And I'm sorry. You didn't react at the time so I was worried it sailed right over your head. That's why I had to call you garbage a second time just now.",author:"",source:"Portal 2",category:"gaming",license:"Fair Use",difficulty:"hard",length:295},{id:"gaming-090",text:"For centuries, human society has taken the gifts of nature for granted. As civilizations grew, humans spread out across the face of the planet, taking what they needed from the land and producing more and more waste materials with little regard for the future.",author:"",source:"Civilization",category:"gaming",license:"Fair Use",difficulty:"hard",length:260},{id:"gaming-091",text:"You're not a mech, but you're enough of a machine to need repair bots now and then. If you used up some bioelectric energy getting through the dark area, for example, this contraption can charge you back up.",author:"",source:"Deus Ex",category:"gaming",license:"Fair Use",difficulty:"hard",length:207},{id:"gaming-092",text:"It all began ages ago, when man's ancestor picked up a shard of a strange red rock. Its power, which was beyond human comprehension, cultivated dreams. In turn, love and hate were born. Only time will see how it all ends.",author:"",source:"Chrono Trigger",category:"gaming",license:"Fair Use",difficulty:"hard",length:221},{id:"gaming-093",text:"Monsters are closing in! Throw your pack against them and push them back into the cage! A hostage will be slowly lowered into the flames! To save the day, you must hit the blue light, to raise the rope. Defeat all monsters before the hostage's goose is cooked!",author:"",source:"Chrono Trigger",category:"gaming",license:"Fair Use",difficulty:"hard",length:260},{id:"gaming-094",text:"We hold our rifles in missing hands. We stand tall on missing legs. We stride forward on the bones of our fallen. Then, and only then, are we alive. This pain is ours and no one else's. A secret weapon we wield, out of sight. We will be stronger than ever.",author:"",source:"Metal Gear Solid",category:"gaming",license:"Fair Use",difficulty:"hard",length:256},{id:"gaming-095",text:"Now! This is it! Now is the time to choose. Die and be free of pain, or live and fight your sorrow! Now is the time to shape your stories! Your fate is in your hands!",author:"",source:"Final Fantasy",category:"gaming",license:"Fair Use",difficulty:"hard",length:166},{id:"gaming-096",text:"There's a diary. Here's the last page. It's all over. The fishmen attack if I make even the slightest noise. I'd rather have my gums scraped than have to fight these fiends.",author:"",source:"Chrono Trigger",category:"gaming",license:"Fair Use",difficulty:"hard",length:173},{id:"gaming-097",text:"It's something Turians are taught from birth. If even one person is still left standing at the end of a war, then the fight was worth it.",author:"",source:"Mass Effect",category:"gaming",license:"Fair Use",difficulty:"medium",length:137},{id:"gaming-098",text:"It is a good life we lead, brother. The best. May it never change. And may it never change us.",author:"",source:"Assassin's Creed",category:"gaming",license:"Fair Use",difficulty:"medium",length:94},{id:"gaming-099",text:"I'm not exactly the expert on this sort of thing - for that you'll have to check in with Sam Carter when you get to Liberty Island - but remember that there's any number of other ways to open a door, including using explosives or finding a security computer.",author:"",source:"Deus Ex",category:"gaming",license:"Fair Use",difficulty:"hard",length:258},{id:"gaming-100",text:"Why did I move here? I guess it was the weather. Or the... Ah, I don't know, that thing. That magic. You see it in the movies. I wanted to retire from what I was doing, you know? From that, that... line of work. Be a good guy for once, a family man. So, I bought a big house. Came here, put my feet up, and thought I'd be a dad like all the other dads. My kids would be like the kids on TV, we play ball and sit in the sun... But well, you know how it is.",author:"",source:"Grand Theft Auto",category:"gaming",license:"Fair Use",difficulty:"hard",length:455},{id:"gaming-101",text:"The right man in the wrong place can make all the difference in the world. So, wake up, Mister Freeman. Wake up and... smell the ashes...",author:"",source:"Half-Life",category:"gaming",license:"Fair Use",difficulty:"medium",length:137},{id:"gaming-102",text:"Come on, let's leave this place. Let's go to the factory and get our airship. This isn't our responsibility - none of it. You just opened a door to this world and we stepped through.",author:"",source:"BioShock",category:"gaming",license:"Fair Use",difficulty:"hard",length:182},{id:"gaming-103",text:"The amount of spent nuclear fuel and plutonium is increasing even today. Listen, have you ever seen a warehouse full of nuclear material? Drums and drums of nuclear waste stacked this high. As far as you can see because there's still no real way to dispose of the stuff.",author:"",source:"Metal Gear Solid",category:"gaming",license:"Fair Use",difficulty:"hard",length:270},{id:"gaming-104",text:"In my restless dreams, I see that town... Silent Hill. You promised me you'd take me there again someday... but you never did. Well I'm alone there now, in our special place... waiting for you.",author:"",source:"Silent Hill",category:"gaming",license:"Fair Use",difficulty:"hard",length:193},{id:"gaming-105",text:"Although the United Nations does not have the power to enforce decisions or compel nations to take military action, the ability to compel member nations to impose economic sanctions against countries guilty of violating security orders gives it significant power in the world stage.",author:"",source:"Civilization",category:"gaming",license:"Fair Use",difficulty:"hard",length:282},{id:"gaming-106",text:"Lord Paladin Tirion Fordring was a powerful man. He was strong in both mind and body, and was counted as one of the greatest warriors of his day. Though he was slightly over fifty years of age, he still looked as fit and dynamic as he had when a younger man. His signature bushy mustache and his neatly trimmed brown hair were streaked with gray, but his piercing green eyes still shone with an energy that belied his years.",author:"",source:"Warcraft III",category:"gaming",license:"Fair Use",difficulty:"hard",length:424},{id:"gaming-107",text:"My friend, do you fly away now? To a world that abhors you and I? All that awaits you is a somber morrow. No matter where the winds may blow. My friend, your desire, is the bringer of life, the gift of the goddess. Even if the morrow is barren of promises, nothing shall forestall my return.",author:"",source:"Final Fantasy",category:"gaming",license:"Fair Use",difficulty:"hard",length:291},{id:"gaming-108",text:"You know, Devin, the way I see it, and hey, I'm no intelligent businessman like you, but the way I see it, there's two great evils that bedevil American capitalism of the kind you practice. Number one is outsourcing. You paid a private company to do your dirty work, and then you underpaid that company because you thought you were big enough and bad enough that you didn't have to play by the rules. Oh, number two: off-shoring your profits.",author:"",source:"Grand Theft Auto",category:"gaming",license:"Fair Use",difficulty:"hard",length:442},{id:"gaming-109",text:"All I asked was for you to behave like a princess. Even royalty must obey rules. Leave the rest up to the Chancellor and forget about the events in town.",author:"",source:"Chrono Trigger",category:"gaming",license:"Fair Use",difficulty:"hard",length:153},{id:"gaming-110",text:"Why are we still here? Just to suffer? Every night, I can feel my leg, and my arm, even my fingers. The body I've lost... and the comrades I've lost... It won't stop hurting, like they're all still there... You feel it too, don't you? I'm gonna make 'em give back our past, take back everything that we've lost. And I won't rest... until we do.",author:"",source:"Metal Gear Solid",category:"gaming",license:"Fair Use",difficulty:"hard",length:344},{id:"gaming-111",text:"You know, I've been in this game for a lot of years and I got out alive. If you want my advice - give up.",author:"",source:"Grand Theft Auto",category:"gaming",license:"Fair Use",difficulty:"medium",length:105},{id:"gaming-112",text:"There's a teleportation grid that runs throughout Halo. That's how the monitor moves about so quickly. I learned how to tap into the grid when I was in the control center. Unfortunately, each jump requires a rather consequential expenditure of energy.",author:"",source:"Halo",category:"gaming",license:"Fair Use",difficulty:"hard",length:251},{id:"gaming-113",text:"I rejected those answers; instead, I chose something different. I chose the impossible. I chose Rapture, a city where the artist would not fear the censor. Where the scientist would not be bound by petty morality. Where the great would not be constrained by the small! And with the sweat of your brow, Rapture can become your city as well.",author:"",source:"BioShock",category:"gaming",license:"Fair Use",difficulty:"hard",length:339},{id:"gaming-114",text:"Enjoy this next test. I'm going to go to the surface. It's a beautiful day out. Yesterday I saw a deer. If you solve this next test, maybe I'll let you ride an elevator all the way up to the break room, and I'll tell you about the time I saw a deer again.",author:"",source:"Portal 2",category:"gaming",license:"Fair Use",difficulty:"hard",length:255},{id:"gaming-115",text:"Hi, Link. Sorry about my yard. It's a little overgrown. Thanks for visiting. I'm glad to have company to talk to. I will tell you an interesting story. There is a lake swimming with Zoras at the source of the river, but it is hard to find. The treasure of Zora can turn people into fish. I'd love to see that.",author:"",source:"The Legend of Zelda",category:"gaming",license:"Fair Use",difficulty:"hard",length:309},{id:"gaming-116",text:"You tell me exactly what you want, and I will very carefully explain to you why it cannot be.",author:"",source:"Grand Theft Auto",category:"gaming",license:"Fair Use",difficulty:"medium",length:93},{id:"gaming-117",text:"Today, computers have taken this ancient art out of the craftsman's workshop and placed it on the desktop. Desktop publishing revolutionized the creation of printed documents, not only from the standpoint of speed and accuracy, but also by enabling anyone to mass-produce the printed word without investing the many years it takes to learn the trade.",author:"",source:"Civilization",category:"gaming",license:"Fair Use",difficulty:"hard",length:350},{id:"gaming-118",text:"The automobile brake was not invented until 1895. Before this, someone had to remain in the car at all times, driving in circles until passengers returned from their errands.",author:"",source:"Portal 2",category:"gaming",license:"Fair Use",difficulty:"hard",length:174},{id:"gaming-119",text:"Nothing looks more suspicious in America than someone who's actually prepared to make something.",author:"",source:"Grand Theft Auto",category:"gaming",license:"Fair Use",difficulty:"medium",length:96},{id:"gaming-120",text:"Some time ago, before the king of Hyrule unified this country, there was a fierce war in our world. One day, to escape from the fires of the war, a Hylian mother and her baby boy entered this forbidden forest. The mother was gravely injured. Her only choice was to entrust the child to the Deku Tree, the guardian spirit of the forest. The Deku Tree could sense that this was a child of destiny, whose fate would affect the entire world, so he took him into the forest. After the mother passed away, the baby was raised as a Kokiri. And now, finally, the day of Destiny has come!",author:"",source:"The Legend of Zelda",category:"gaming",license:"Fair Use",difficulty:"hard",length:579},{id:"gaming-121",text:"Without warning the Halon system goes off. Pillars of high-pressure gas flood into the room, sucking the oxygen out of the air, making it impossible for a fire to breathe. A fire. Or people.",author:"",source:"Resident Evil",category:"gaming",license:"Fair Use",difficulty:"hard",length:190},{id:"gaming-122",text:"Hero of Hyrule, chosen by the sword that seals the darkness. You have shown unflinching bravery and skill in the face of darkness and adversity, and have proven yourself worthy of the blessings of the goddess Hylia. Whether skyward bound, adrift in time, or steeped in the glowing embers of twilight, the sacred blade is forever bound to the soul of the hero.",author:"",source:"The Legend of Zelda",category:"gaming",license:"Fair Use",difficulty:"hard",length:359},{id:"gaming-123",text:"We are amidst strange beings, in a strange land. The flow of time itself is convoluted, with heroes centuries old phasing in and out. The very fabric wavers and relations shift and obscure. There's no telling how much longer your world and mine will remain in contact. But, use this, to summon one another as spirits, cross the gaps between the worlds, and engage in jolly cooperation!",author:"",source:"Dark Souls",category:"gaming",license:"Fair Use",difficulty:"hard",length:385},{id:"gaming-124",text:"This won't take long. There. That should give us enough time to make it to a lifeboat.",author:"",source:"Halo",category:"gaming",license:"Fair Use",difficulty:"medium",length:86},{id:"gaming-125",text:"Some men dream of money, some men dream of love. My father dreamt of a flood of fire. We were given Eden, and we turned it into Sodom. Why do we deserve salvation? The Lord gave Noah a fish in the form of a flood. But he was not so easy on me.",author:"",source:"BioShock",category:"gaming",license:"Fair Use",difficulty:"hard",length:243},{id:"gaming-126",text:"According to the data in their networks the ring has some kind of deep religious significance. If I'm analyzing this correctly they believe that Halo is some kind of weapon - one with vast, unimaginable power.",author:"",source:"Halo",category:"gaming",license:"Fair Use",difficulty:"hard",length:209},{id:"gaming-127",text:"Paper as we know it today was invented in China in around 100 AD. Wood and other fibrous material is mixed with liquid and mashed into a pulp, which is then poured onto fine screens. The liquid drains away, leaving a thin layer of fibrous material on the wire. When this material dries, it becomes paper.",author:"",source:"Civilization",category:"gaming",license:"Fair Use",difficulty:"hard",length:304},{id:"gaming-128",text:"Mankind continues to fight, but it is a desperate fight to stay alive. I suppose that he chose a life of warfare since that was the only way he knew. Like you, Father, he chose of a path of destruction... Farewell, land of my birth. Never again will these eyes gaze upon your beauty.",author:"",source:"Castlevania",category:"gaming",license:"Fair Use",difficulty:"hard",length:283},{id:"gaming-129",text:"This was a triumph! I'm making a note here: huge success! It's hard to overstate my satisfaction. Aperture Science: we do what we must, because we can. For the good of all of us, except the ones who are dead. But there's no sense crying over every mistake. You just keep on trying 'til you run out of cake. And the science gets done, and you make a neat gun for the people who are still alive.",author:"",source:"Portal",category:"gaming",license:"Fair Use",difficulty:"hard",length:393},{id:"gaming-130",text:"The theory of music emphasizes the elements from which music is composed. One such structure is the melody, which is a grouping of musical notes that combine into a basic, but immensely flexible structure. Another is the chord, which is two or more notes played simultaneously to create a harmony.",author:"",source:"Civilization",category:"gaming",license:"Fair Use",difficulty:"hard",length:297},{id:"gaming-131",text:"The Inca believed that if one did not give thanks and obedience to the gods, bad things would happen. The world of the Andes Mountains is full of ecological wonders - and ecological disasters such as earthquakes, severe storms, and volcanic activity.",author:"",source:"Civilization",category:"gaming",license:"Fair Use",difficulty:"hard",length:250},{id:"gaming-132",text:"It was right before I was to take on my duties of protecting the President's daughter when she was abducted. That's the ultimate reason I'm in this lonely and rural part of Europe. According to our intelligence, there's reliable information of a sighting of a girl that looks very similar to the President's daughter. Apparently she's being withheld by some unidentified group of people. Who would have thought my first job would be a rescue mission?",author:"",source:"Resident Evil",category:"gaming",license:"Fair Use",difficulty:"hard",length:450},{id:"gaming-133",text:"I offered her a job at the desk. You can imagine what she said to that. If the economy hadn't bottomed out, she might have got along all right.",author:"",source:"Deus Ex",category:"gaming",license:"Fair Use",difficulty:"medium",length:143},{id:"gaming-134",text:"Always remember the four basic tactics to avoid detection: crouch behind concealment, stay behind enemies, move slowly to avoid making noise, and use shadows to conceal yourself. Be alert to every possibility.",author:"",source:"Deus Ex",category:"gaming",license:"Fair Use",difficulty:"hard",length:209},{id:"gaming-135",text:"This hole was caused by some kind of explosive. Pretty powerful if it tore through the ship's hull. All I detect down there are pools of coolant. We should continue our search somewhere else.",author:"",source:"Halo",category:"gaming",license:"Fair Use",difficulty:"hard",length:191},{id:"gaming-136",text:"We'll use a process that I discovered called gene targeting. The strongest soldiers don't become what they are by acquiring their skills through training or experience, we now know that hereditary factors are far more crucial for creating superior soldiers.",author:"",source:"Metal Gear Solid",category:"gaming",license:"Fair Use",difficulty:"hard",length:257},{id:"gaming-137",text:"For you, the day Bison graced your village, was the most important day in your life. But for me, it was Tuesday.",author:"",source:"Street Fighter",category:"gaming",license:"Fair Use",difficulty:"medium",length:112},{id:"gaming-138",text:"Set in Liberty City. Meltdown! It's all being shot on green screen right out back. We take a look at the financial crisis, and then we boil it all down to a really simplistic battle between two yuppies, with lots of training montages.",author:"",source:"Grand Theft Auto",category:"gaming",license:"Fair Use",difficulty:"hard",length:234},{id:"gaming-139",text:"The machinery in these canyons are Halo's primary firing mechanisms. They consist of three phase pulse generators that amplify Halo's signal and allow it to fire deep into space. The power levels are enormous. I can't even begin to calculate the pulse's range.",author:"",source:"Halo",category:"gaming",license:"Fair Use",difficulty:"hard",length:260},{id:"gaming-140",text:"Our files show that the Smuggler is whacked-out paranoid. Watch for booby traps. And the latest news: your brother's team hit some resistance, so they're going to be delayed while we bring in chopper support.",author:"",source:"Deus Ex",category:"gaming",license:"Fair Use",difficulty:"hard",length:208},{id:"gaming-141",text:`Hating the Empire, getting revenge... It's all I ever thought about. But I never did anything about it. I mean, I realized there was nothing I could do. It made me feel hollow, alone. And then... I'd miss my brother. I'd say stuff like "I'm gonna be a sky pirate", or some other stupid thing. Just anything to keep my mind off it. I was just... I was running away. I needed to get away from his death.`,author:"",source:"Final Fantasy",category:"gaming",license:"Fair Use",difficulty:"hard",length:401},{id:"gaming-142",text:"Three shiny steel doors stand at the centre of the hallway. Bodies are everywhere. Killed as they waited for an elevator. The eerie silence is broken by a scratching sound. One of the elevator doors pops open an inch. Hands force their way out.",author:"",source:"Resident Evil",category:"gaming",license:"Fair Use",difficulty:"hard",length:244},{id:"gaming-143",text:"The hallway is luxurious and tasteful. Tapestries and paintings of old relatives that Alice doesn't recognize adorn the walls. But this isn't a quaint old house. There's something in the air.",author:"",source:"Resident Evil",category:"gaming",license:"Fair Use",difficulty:"hard",length:191},{id:"gaming-144",text:"There is no hate, only joy. For you are beloved by the goddess. Hero of the dawn, Healer of worlds. Dreams of the morrow hath the shattered soul. Pride is lost. Wings stripped away, the end is nigh.",author:"",source:"Final Fantasy",category:"gaming",license:"Fair Use",difficulty:"hard",length:198},{id:"gaming-145",text:`I bet he was referring to the four areas just outside town. There's one in each compass direction. But what do you suppose he meant by "the four who are there?"`,author:"",source:"The Legend of Zelda",category:"gaming",license:"Fair Use",difficulty:"hard",length:160},{id:"gaming-146",text:"After the victory at Wounded Knee, the angel of Columbia did present herself to Father Comstock and show him a vision of the future. And so our Prophet led the people away from the Sodom Below, up, up into the city, where they created an even more perfect union. But it was the miracle child, the lamb, that is the future of our city. For the Prophet has said that she in the tower will lead the Sodom Below into righteousness.",author:"",source:"BioShock",category:"gaming",license:"Fair Use",difficulty:"hard",length:427},{id:"gaming-147",text:"They show you stuff in the military. You wanna know the real battlefield, it's microscopic. We can't even see it. Lucky for me, I got immunizations, but that guy... Well, once you're infected, you're infected.",author:"",source:"Deus Ex",category:"gaming",license:"Fair Use",difficulty:"hard",length:209},{id:"gaming-148",text:"So Michael, this is where dead men come back to life. It's been nearly ten years. But you'll keep for another day or so huh, old friend? I grieved for you! You weren't even dead. You were my best friend. Well, guess who's coming to your doorstep!",author:"",source:"Grand Theft Auto",category:"gaming",license:"Fair Use",difficulty:"hard",length:246},{id:"gaming-149",text:"In the first age, in the first battle, when the shadows first lengthened, one stood. Burned by the embers of Armageddon, his soul blistered by the fires of Hell and tainted beyond ascension, he chose the path of perpetual torment. In his ravenous hatred he found no peace; and with boiling blood he scoured the Umbral Plains seeking vengeance against the dark lords who had wronged him. He wore the crown of the Night Sentinels, and those that tasted the bite of his sword named him... the Doom Slayer.",author:"",source:"DOOM",category:"gaming",license:"Fair Use",difficulty:"hard",length:502},{id:"gaming-150",text:"I sense that a mighty evil force guides the wizard's actions and augments his magical power. The only weapon potent enough to defeat the wizard is the legendary Master Sword. It is said that the village elder is a descendant of one of the seven wise men. Maybe he can tell you more. I will mark his house on your map. But watch your every move! I am certain that the castle soldiers will be looking for you now! I will hide Princess Zelda here. Do not worry! Seek the elder!",author:"",source:"The Legend of Zelda",category:"gaming",license:"Fair Use",difficulty:"hard",length:474},{id:"gaming-151",text:"The spirits burned up in its ominous flame lose their way and wander this world forever.",author:"",source:"Pokemon",category:"gaming",license:"Fair Use",difficulty:"medium",length:88},{id:"gaming-152",text:"We have a straight shot into the fusion reactor. We need a catalyst explosion to destabilize the magnetic containment fields surrounding the fusion cells. Use an explosive. I recommend a grenade or rocket. If you run out of explosives, there is an armory station located near the engine room's entrance.",author:"",source:"Halo",category:"gaming",license:"Fair Use",difficulty:"hard",length:303},{id:"gaming-153",text:"Then listen up! When I joined the Corps, we didn't have any fancy schmancy tanks! We had sticks! Two sticks and a rock for a whole platoon. And we had to share the rock. Buck up, boy, you're one very lucky marine!",author:"",source:"Halo",category:"gaming",license:"Fair Use",difficulty:"hard",length:213},{id:"gaming-154",text:"I appreciate your concern, Cortana, but it's not up to me, protocol is clear. Destruction or capture of the shipboard AI is absolutely unacceptable, and that means you're leaving the ship. Lock in a selection of emergency landing zones, upload them to my neural lace and then sort yourself for hard transfer.",author:"",source:"Halo",category:"gaming",license:"Fair Use",difficulty:"hard",length:308},{id:"gaming-155",text:"Oh, hello there. I will stay behind, to gaze at the sun. The sun is a wondrous body. Like a magnificent father! If only I could be so grossly incandescent!",author:"",source:"Dark Souls",category:"gaming",license:"Fair Use",difficulty:"hard",length:155},{id:"gaming-156",text:"They were all dead. The final gunshot was an exclamation mark to everything that had led to this point. I released my finger from the trigger. And then it was over.",author:"",source:"Max Payne",category:"gaming",license:"Fair Use",difficulty:"hard",length:164},{id:"gaming-157",text:"Let's go to a place where everything is made of blocks, and the only limit is your imagination. Let's go wherever you want to go. Climb the tallest mountains, venture down to the darkest caves. Build whatever you want; day or night, rain or shine, because this is the most significant sandbox you'll ever set foot in. Build a majestic castle, invent a new machine, or take a ride on a roller coaster. Play with friends, build your little community. Protect yourself with the strongest armor that you can craft, and fight off the danger of the night. No one can tell you what you can or cannot do. With no rules to follow, this adventure is up to you.",author:"",source:"Minecraft",category:"gaming",license:"Fair Use",difficulty:"hard",length:650},{id:"gaming-158",text:"There is nothing. Only warm, primordial blackness. Your conscience ferments in it, no larger than a single grain of malt.",author:"",source:"Disco Elysium",category:"gaming",license:"Fair Use",difficulty:"medium",length:121},{id:"gaming-159",text:"I had a son... he passed away. I had a girl who loved me... I threw that away. My momma died when I was a kid... and my daddy... well, I watched him die... and it weren't soon enough.",author:"",source:"Red Dead Redemption",category:"gaming",license:"Fair Use",difficulty:"hard",length:183},{id:"gaming-160",text:"Stop! Enough! I have heard more than enough to render my judgment. For as long as I have known you, Holger, you have spun words into lies. You weaken the minds of children, and delude the minds of men. I've shown you too many years of tolerance. And rather than exist in grateful meekness, as Holger the liar, you sink lower. You become Holger the Thief, robbing a woman of her livelihood, all in the name of your stupid stories!",author:"",source:"Assassin's Creed",category:"gaming",license:"Fair Use",difficulty:"hard",length:429},{id:"gaming-161",text:"Evil is evil. Lesser, greater, middling... makes no difference. The degree is arbitrary. The definition's blurred. If I'm to choose between one evil and another, I'd rather not choose at all.",author:"",source:"The Witcher 3: Wild Hunt",category:"gaming",license:"Fair Use",difficulty:"hard",length:191},{id:"gaming-162",text:"This cave is not a natural formation. Someone built it, so it must lead somewhere. I've hacked into the Covenant battlenet.",author:"",source:"Halo",category:"gaming",license:"Fair Use",difficulty:"medium",length:123},{id:"gaming-163",text:"Look at you, Hacker. A pathetic creature of meat and bone, panting and sweating as you run through my corridors. How can you challenge a perfect, immortal machine?",author:"",source:"System Shock",category:"gaming",license:"Fair Use",difficulty:"hard",length:163},{id:"gaming-164",text:"In my restless dreams, I see that town. Silent Hill. You promised me you'd take me there again someday. But you never did. Well, I'm alone there now... In our 'special place'... Waiting for you... Waiting for you to come to see me. But you never do. And so I wait, wrapped in my cocoon of pain and loneliness. I know I've done a terrible thing to you. Something you'll never forgive me for. I wish I could change that, but I can't. I feel so pathetic and ugly laying here, waiting for you... Every day I stare up at the cracks in the ceiling and all I can think about is how unfair it all is... The doctor came today. He told me I could go home for a short stay. It's not that I'm getting better. It's just that this may be my last chance... I think you know what I mean... Even so, I'm glad to be coming home. I've missed you terribly. But I'm afraid, James. I'm afraid you don't really want me to come home. Whenever you come see me, I can tell how hard it is on you... I don't know if you hate me or pity me... Or maybe I just disgust you... I'm sorry about that. When I first learned that I was going to die, I just didn't want to accept it. I was so angry all the time and I struck out at everyone I loved most. Especially you, James. That's why I understand if you do hate me. But I want you to know this, James. I'll always love you. Even though our life together had to end like this, I still wouldn't trade it for the world. We had some wonderful years together. Well, this letter has gone on too long, so I'll say goodbye. I told the nurse to give this to you after I'm gone. That means that as you read this, I'm already dead. I can't tell you to remember me, but I can't bear for you to forget me. These last few years since I became ill... I'm so sorry for what I did to you, did to us... You've given me so much and I haven't been able to return a single thing. That's why I want you to live for yourself now. Do what's best for you, James. James... You made me happy.",author:"",source:"Silent Hill",category:"gaming",license:"Fair Use",difficulty:"hard",length:1982},{id:"gaming-165",text:"They let me pick. Did I ever tell you that? Choose whichever Spartan I wanted. You know me. I did my research, watched as you became the soldier we needed you to be. Like the others, you were strong and swift and brave. A natural leader. But you had something they didn't. Something no one saw but me. Can you guess? Luck... Was I wrong?",author:"",source:"Halo",category:"gaming",license:"Fair Use",difficulty:"hard",length:337},{id:"gaming-166",text:"Well, you know the old formula: Comedy equals tragedy plus time. And you have been asleep for a while. So I guess it's actually pretty funny when you do the math.",author:"",source:"Portal 2",category:"gaming",license:"Fair Use",difficulty:"hard",length:162},{id:"gaming-167",text:"'Cause you are unfixable, I can't break through your world. 'Cause you live in shades of cool, your heart is unbreakable.",author:"",source:"Hades",category:"gaming",license:"Fair Use",difficulty:"medium",length:121},{id:"gaming-168",text:"But you didn't get this far by giving up, did you? That's right. You have something called determination. So as long as you hold on... so long as you do what's in your heart... I believe you can do the right thing.",author:"",source:"Undertale",category:"gaming",license:"Fair Use",difficulty:"hard",length:214},{id:"gaming-169",text:"Don't you realize that being nice just makes you get hurt? Look at yourself. You made all these great friends... But now, you'll probably never see them again. Not to mention how much they've been set back by you. Hurts, doesn't it? If you had just gone through without caring about anyone, you wouldn't have to feel bad now. So I don't get it. If you really did everything the right way, why did things still end up like this?",author:"",source:"Undertale",category:"gaming",license:"Fair Use",difficulty:"hard",length:427},{id:"gaming-170",text:"Why were you using a treadmill in the dark? Is Sans pranking you across time and space? I hate it when he does that!",author:"",source:"Undertale",category:"gaming",license:"Fair Use",difficulty:"medium",length:116},{id:"gaming-171",text:"Science isn't about WHY. It's about WHY NOT. Why is so much of our science dangerous? Why not marry safe science if you love it so much. In fact, why not invent a special safety door that won't hit you on the butt on the way out, because you are fired.",author:"",source:"Portal 2",category:"gaming",license:"Fair Use",difficulty:"hard",length:252},{id:"gaming-172",text:"I'd give my life, not for honor, but for you! In my time, there'll be no one else. Crime, it's the way I fly to you!",author:"",source:"Metal Gear Solid",category:"gaming",license:"Fair Use",difficulty:"medium",length:116},{id:"gaming-173",text:"Long ago, the world was nothing more than an endless sea cloaked in a boundless sky, reaching as far as could possibly be imagined. Then two great titans came into existence. The Bionis and the Mechonis. The titans were locked in a timeless battle. Until at last... Only their lifeless corpses remained.",author:"",source:"Xenoblade",category:"gaming",license:"Fair Use",difficulty:"hard",length:303},{id:"gaming-174",text:"Next time you have a vision, you tell us. We bear the burden together, as a team. You have a vision you don't like, we'll change the future together.",author:"",source:"Xenoblade",category:"gaming",license:"Fair Use",difficulty:"medium",length:149},{id:"gaming-175",text:"I can't kill you, but I can stop your blade. And I'll do it over and over again, until... we understand each other. OK?",author:"",source:"Xenoblade",category:"gaming",license:"Fair Use",difficulty:"medium",length:119},{id:"gaming-176",text:"Ganon was born out of a dark past. He is a pure embodiment of the ancient evil that is reborn time and time again... He has given up on reincarnation and assumed his pure, enraged form. If set free upon our world, the destruction will be unlike anything ever seen before. I entrust you with the Bow of Light - a powerful weapon in the face of evil. Link... you may not yet be at a point where you have fully recovered your power or all of your memories... But courage need not be remembered... for it is never forgotten.",author:"",source:"The Legend of Zelda",category:"gaming",license:"Fair Use",difficulty:"hard",length:520},{id:"gaming-177",text:"What has just appeared is Team Plasma's castle. The king's words will resound from the heights to all below. You must come to the castle, as well. Everything will be decided there. Whether Pokemon will be liberated from people, or whether Pokemon and people will live together… We will see whose belief is stronger... And our result will change the world.",author:"",source:"Pokemon",category:"gaming",license:"Fair Use",difficulty:"hard",length:355},{id:"gaming-178",text:"We are the universe. We are everything you think isn't you. You are looking at us now, through your skin and your eyes. And why does the universe touch your skin, and throw light on you? To see you, player. To know you. And to be known. I shall tell you a story.",author:"",source:"Minecraft",category:"gaming",license:"Fair Use",difficulty:"hard",length:262},{id:"gaming-179",text:"War has changed. It's no longer about nations, ideologies, or ethnicity. It's an endless series of proxy battles, fought by mercenaries and machines. War - and its consumption of life - has become a well-oiled machine. War has changed. ID-tagged soldiers carry ID-tagged weapons, use ID-tagged gear. Nanomachines inside their bodies enhance and regulate their abilities. Genetic control, information control, emotion control, battlefield control... everything is monitored and kept under control. War... has changed. The age of deterrence has become the age of control, all in the name of averting catastrophe from weapons of mass destruction, and he who controls the battlefield, controls history. War... has changed. When the battlefield is under total control, war becomes routine.",author:"",source:"Metal Gear Solid",category:"gaming",license:"Fair Use",difficulty:"hard",length:784},{id:"gaming-180",text:"Hello and, again, welcome to the Aperture Science computer-aided enrichment center. We hope your brief detention in the relaxation vault has been a pleasant one. Your specimen has been processed and we are now ready to begin the test proper.",author:"",source:"Portal",category:"gaming",license:"Fair Use",difficulty:"hard",length:241},{id:"gaming-181",text:"Please be advised that a noticeable taste of blood is not part of any test protocol but is an unintended side effect of the Aperture Science Material Emancipation Grill, which may, in semi-rare cases, emancipate dental fillings, crowns, tooth enamel, and teeth.",author:"",source:"Portal",category:"gaming",license:"Fair Use",difficulty:"hard",length:261},{id:"gaming-182",text:"The vital apparatus vent will deliver a weighted companion cube in three, two, one. This weighted companion cube will accompany you through the test chamber. Please take care of it.",author:"",source:"Portal",category:"gaming",license:"Fair Use",difficulty:"hard",length:181},{id:"gaming-183",text:"I see, your HEV-Suit still fits you like a glove. At least the glove parts do.",author:"",source:"Half-Life",category:"gaming",license:"Fair Use",difficulty:"easy",length:78},{id:"gaming-184",text:"But I want you to know this, James. I'll always love you. Even though our life together had to end like this, I still wouldn't trade it for the world. We had some wonderful years together. Well, this letter has gone on too long, so I'll say goodbye. I told the nurse to give this to you after I'm gone. That means that as you read this, I'm already dead. I can't tell you to remember me, but I can't bear for you to forget me. These last few years since I became ill... I'm so sorry for what I did to you, did to us... You've given me so much and I haven't been able to return a single thing. That's why I want you to live for yourself now. Do what's best for you, James. James... You made me happy.",author:"",source:"Silent Hill",category:"gaming",license:"Fair Use",difficulty:"hard",length:699},{id:"gaming-185",text:"Although Ganon is gone for now, there is still so much more for us to do, and so many painful memories that we must bear.",author:"",source:"The Legend of Zelda",category:"gaming",license:"Fair Use",difficulty:"medium",length:121},{id:"gaming-186",text:"Link... You are the light. Our light... That must shine upon Hyrule once again. Now go.",author:"",source:"The Legend of Zelda",category:"gaming",license:"Fair Use",difficulty:"medium",length:87},{id:"gaming-187",text:"All right, I've been thinking. When life gives you lemons? Don't make lemonade. Make life take the lemons back! Get mad! I don't want your damn lemons! What am I supposed to do with these?! Demand to see life's manager! Make life rue the day it thought it could give Cave Johnson lemons! Do you know who I am?! I'm the man who's gonna burn your house down! With the lemons! I'm gonna get my engineers to invent a combustible lemon that burns your house down!",author:"",source:"Portal 2",category:"gaming",license:"Fair Use",difficulty:"hard",length:458},{id:"gaming-188",text:`Well done. Here come the test results: "You are a horrible person." That's what it says: a horrible person. We weren't even testing for that.`,author:"",source:"Portal 2",category:"gaming",license:"Fair Use",difficulty:"medium",length:141},{id:"gaming-189",text:"Okay. Look. We both said a lot of things that you're going to regret. But I think we can put our differences behind us. For science. You monster.",author:"",source:"Portal 2",category:"gaming",license:"Fair Use",difficulty:"medium",length:145},{id:"gaming-190",text:"While it is true that man succumbs all too often to anger and avarice, he may yet overcome his baser instincts through the forming of bonds with others.",author:"",source:"Final Fantasy",category:"gaming",license:"Fair Use",difficulty:"hard",length:152},{id:"gaming-191",text:"Save your tears for the morrow. You may be sure we will have ample cause to shed them, be they for joy or despair.",author:"",source:"Final Fantasy",category:"gaming",license:"Fair Use",difficulty:"medium",length:114},{id:"gaming-192",text:"We fought and we fought and we fought... until there was no one left to fight. We won... and now our world is being erased from existence. We did everything right, everything that was asked of us, and still - still it came to this!",author:"",source:"Final Fantasy",category:"gaming",license:"Fair Use",difficulty:"hard",length:231},{id:"gaming-193",text:"Stay strong. Keep the faith. At duty's end, we will meet again. We will. We will.",author:"",source:"Final Fantasy",category:"gaming",license:"Fair Use",difficulty:"medium",length:81},{id:"gaming-194",text:"The rains have ceased, and we have been graced with another beautiful day. But you are not here to see it.",author:"",source:"Final Fantasy",category:"gaming",license:"Fair Use",difficulty:"medium",length:106},{id:"gaming-195",text:"We are the stories we tell ourselves. The brave hero, the tortured soul, the altruist, the pragmatist. They will tell you who they see, but you and you alone know who you are. For I speak only for myself. If you find comfort in my words, they are yours for the taking, but that is your choice. Now and ever after, as it has always been.",author:"",source:"Final Fantasy",category:"gaming",license:"Fair Use",difficulty:"hard",length:336},{id:"gaming-196",text:"The glory of the heavens was ever beyond the grasp of those who never thought to reach for it. But if I've gained anything from all of this, it is the courage to stretch out my hand.",author:"",source:"Final Fantasy",category:"gaming",license:"Fair Use",difficulty:"hard",length:182},{id:"gaming-197",text:"Lands that stretched on forever. Skies one could drown in. The heartbeat of nature. Silent, yet strong. And amidst it all a people. Beacons of light and life. Laughter that warmed my heart like naught else before. They are my meaning and my purpose. My love. In spite of... or perhaps because of this, I choose to believe. In mankind's potential. In his ability to find a way forward. So let there be no way back! From that temptation, I sunder us! No more shall man have wings to bear him to paradise! Henceforth, he shall walk!",author:"",source:"Final Fantasy",category:"gaming",license:"Fair Use",difficulty:"hard",length:529},{id:"gaming-198",text:"A sea of shimmering stars. Diamonds strewn across a raven gown, boundless and beautiful. 'Tis an exquisite sight not unlike the Source. Calm and gentle... and forgiving. For however deep the void, or wide the expanse, there is no shore so distant as to be beyond the reach of light.",author:"",source:"Final Fantasy",category:"gaming",license:"Fair Use",difficulty:"hard",length:282},{id:"gaming-199",text:"Aye, it's true. We've lost much and more. Known unimaginable suffering. But through it all, we never, ever forgot what was dear to us. And that's what gave us the strength to carry on.",author:"",source:"Final Fantasy",category:"gaming",license:"Fair Use",difficulty:"hard",length:184},{id:"gaming-200",text:"If you like, I will tell you a tale. A tale of a world on the brink. Of a people who never gave up on the future. Of a man who realized his grandest dreams, and then awakened to a grander reality.",author:"",source:"Final Fantasy",category:"gaming",license:"Fair Use",difficulty:"hard",length:196},{id:"gaming-201",text:"All is excruciating pain. I breathe fire and torment. I birth a world of suffering to mire and plague. In one fleeting moment, lives come and go. Ever moving towards the unknown. And in that fleeting moment, they cry for the answer to the question: Why, given life, are they meant to suffer, to die… As fragmented, imperfect beings, yours is a never-ending quest. A quest to find your purpose, knowing your end is assured. To find the strength to continue, when all strength has left you. To find joy, even as darkness descends… And amidst deepest despair, light everlasting.",author:"",source:"Final Fantasy",category:"gaming",license:"Fair Use",difficulty:"hard",length:575},{id:"gaming-202",text:"Tell me, have you been to the ruins beneath the waters of the Bounty? Or the treasure islands beyond the frozen waters of Blindfrost, in Orthard's north? The fabled golden cities of the New World? The sacred sites of the forgotten people of the south sea isles? What about Meracydia, the southern continent? Do you know aught of its present state of affairs? …I thought not. Even of your little Eorzea, you know precious little. The true identities of the Twelve, for instance. All of which is to say: expand your horizons. Go forth and seek discovery.",author:"",source:"Final Fantasy",category:"gaming",license:"Fair Use",difficulty:"hard",length:552},{id:"gaming-203",text:"Know this, my children. There is more ugliness than beauty in this world. To live is to suffer. To drink of calamity and drown in anguish. To toil and be tested, always and ever. 'Tis a perilous path you walk. Death lurks in the dark, and is the sole promise that awaits at journey's end. You will tremble with terror. You will weep tears of anger and despair. But do not avert your eyes. See your life for what it is. Then you will see how the hardships make you strong. Every doubt reforged as scales for your armor. Every agony to temper your blade.",author:"",source:"Final Fantasy",category:"gaming",license:"Fair Use",difficulty:"hard",length:552},{id:"gaming-204",text:"As a child, I considered such unknowns sinister. Now, though, I understand they bear no ill will. The universe is, and we are.",author:"",source:"Outer Wilds",category:"gaming",license:"Fair Use",difficulty:"medium",length:126},{id:"gaming-205",text:"We do not have much connection, you and I. Still, this encounter feels special. I hope you won't mind if I think of you as a friend.",author:"",source:"Outer Wilds",category:"gaming",license:"Fair Use",difficulty:"medium",length:132},{id:"gaming-206",text:"When my kind found the Eye and realized what it was capable of, they were terrified. It was too difficult a truth. Like a light too bright to look upon directly, it burned them. What they could not unlearn was hidden away in darkness - obfuscated, then lost. They did not want to see their story end.",author:"",source:"Outer Wilds",category:"gaming",license:"Fair Use",difficulty:"hard",length:300},{id:"gaming-207",text:"I've been having these weird thoughts lately - like is any of this for real, or not?",author:"",source:"Kingdom Hearts",category:"gaming",license:"Fair Use",difficulty:"medium",length:84},{id:"gaming-208",text:"A scattered dream that's like a far-off memory. A far-off memory that's like a scattered dream. I want to line the pieces up - yours and mine.",author:"",source:"Kingdom Hearts",category:"gaming",license:"Fair Use",difficulty:"medium",length:142},{id:"gaming-209",text:"That dream again... I've been having the same dream over and over again for as long as I can remember. An unfamiliar world filled with unfamiliar faces and unfamiliar good-byes... As if I'm experiencing a life that belonged to someone else. This island surrounded by smaller desolate isles, a vast ocean, and a never-ending sky - this is my entire world. But maybe there's something beyond these waters. Maybe there are worlds like the ones I dream of. If I could get to the outside world, would I be able to meet my friends from my dreams? I can't get the thought out of my head as I lie on the sand like a starfish day after day, feeling like I'm falling through the sky.",author:"",source:"Kingdom Hearts",category:"gaming",license:"Fair Use",difficulty:"hard",length:673},{id:"gaming-210",text:"Those who are weak, and who desire greater power, simply strip the strong of their power, and convince themselves they've earned it. That's how people become tainted by darkness. They believe what they want to believe, using hollow reasons as justification. They repeat this cycle, and their darkness grows.",author:"",source:"Kingdom Hearts",category:"gaming",license:"Fair Use",difficulty:"hard",length:307},{id:"gaming-211",text:"Long ago, two races ruled over Earth: Humans and Monsters. One day, war broke out between the two races. After a long battle, the humans were victorious. They sealed the monsters underground with a magic spell. Many years later... Mt. Ebott, 201X. Legends say that those who climb the mountain never return.",author:"",source:"Undertale",category:"gaming",license:"Fair Use",difficulty:"hard",length:307},{id:"gaming-212",text:"And use well what brief time you have with one another, whilst you can. As mortals do.",author:"",source:"Hades",category:"gaming",license:"Fair Use",difficulty:"medium",length:86},{id:"gaming-213",text:"Haven't I done a great job at protecting you? I mean, look at yourself. You haven't died a single time.",author:"",source:"Undertale",category:"gaming",license:"Fair Use",difficulty:"medium",length:103}];export{e as default};
